  const unknown = Object.keys(named).filter((key) => !allowed.has(key));
  if (unknown.length !== 0) {
    throw new TypeError(`Unknown optional argument '${unknown.join("', '")}' for ${operation}; expected keys: ${names.join(", ")}`);
  }
